        if not math.isfinite(a):
            raise ValueError("retrace advantage must be finite")
        target = v + a
        if not math.isfinite(target):
            raise ValueError("retrace target must be finite")
        advantages[t] = a
        targets[t] = target
        nc = cs[t]
    return {"targets": targets, "advantages": advantages}


